import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val n = br.readLine().trim().toInt()
    val s = br.readLine().trim()
    val m = s.length

    val fail = IntArray(m)
    var k = 0
    for (i in 1 until m) {
        while (k > 0 && s[i] != s[k]) k = fail[k - 1]
        if (s[i] == s[k]) k++
        fail[i] = k
    }

    fun delta(q: Int, c: Char): Int {
        var kk = q
        while (kk > 0 && s[kk] != c) kk = fail[kk - 1]
        if (s[kk] == c) kk++
        return kk
    }

    val M = Array(m) { LongArray(m) }
    for (i in 0 until m) {
        for (c in charArrayOf('0', '1')) {
            val j = delta(i, c)
            if (j < m) M[i][j] += 1
        }
    }

    fun multiply(a: Array<LongArray>, b: Array<LongArray>): Array<LongArray> {
        val size = a.size
        val res = Array(size) { LongArray(size) }
        for (i in 0 until size) {
            for (kk in 0 until size) {
                val aik = a[i][kk]
                if (aik == 0L) continue
                for (j in 0 until size) {
                    res[i][j] += aik * b[kk][j]
                }
            }
        }
        return res
    }

    var result = Array(m) { i -> LongArray(m) { j -> if (i == j) 1L else 0L } }
    var base = M
    var e = n
    while (e > 0) {
        if (e and 1 == 1) {
            result = multiply(result, base)
        }
        base = multiply(base, base)
        e = e shr 1
    }

    var trace = 0L
    for (i in 0 until m) trace += result[i][i]

    val total = 1L shl n
    println(total - trace)
}
